// Situation: College project had performance issues
// My strength: systematic debugging and optimization

public class OrderProcessor {
    // Original: O(n²) nested loop causing timeout
    // My optimization: changed data structure

    private Map<Long, Order> orderCache = new HashMap<>();

    public List<Order> findMatchingOrders(List<Long> orderIds) {
        var results = new ArrayList<Order>();

        for (var id : orderIds) {
            // Changed from nested search to O(1) lookup
            var order = orderCache.get(id);
            if (order != null) {
                results.add(order);
            }
        }

        return results;
        // Result: reduced processing time from 3s to 50ms
    }
}

