// My failure: deployed code that crashed on null inputs
// Lesson: now I validate inputs explicitly

public class UserValidator {

    // Before: assumed inputs were always valid
    // public boolean isValidEmail(String email) {
    //     return email.contains("@") && email.contains(".");
    // }
    // ^ Crashed with NullPointerException in production

    // After: learned to validate inputs first
    public boolean isValidEmail(String email) {
        if (email == null || email.isBlank()) {
            return false;  // handle null/empty explicitly
        }

        // Now I think through edge cases first
        return email.contains("@") 
            && email.indexOf("@") > 0
            && email.lastIndexOf(".") > email.indexOf("@");
    }

    // New habit: write tests for null, empty, invalid first
}

