// My strength: writing code that's easy to maintain
// Feedback: teammates said my code was easiest to understand

public class DiscountCalculator {

    private static final double LOYALTY_THRESHOLD = 1000.0;
    private static final double LOYALTY_DISCOUNT = 0.10;
    private static final double BULK_THRESHOLD = 500.0;
    private static final double BULK_DISCOUNT = 0.05;

    public double calculateDiscount(Order order) {
        if (isLoyalCustomer(order.getCustomer())) {
            return order.getTotal() * LOYALTY_DISCOUNT;
        }

        if (isBulkOrder(order)) {
            return order.getTotal() * BULK_DISCOUNT;
        }

        return 0.0;  // no discount
    }

    private boolean isLoyalCustomer(Customer customer) {
        return customer.getTotalSpent() >= LOYALTY_THRESHOLD;
    }

    private boolean isBulkOrder(Order order) {
        return order.getTotal() >= BULK_THRESHOLD;
    }

    // Professor used this in lecture: "See how readable this is?"
}

