// Topic I find hard: concurrency and thread safety
// Why: race conditions are invisible until they break

public class CounterService {

    // WRONG (my initial attempt): not thread-safe
    // private int counter = 0;
    // public void increment() {
    //     counter++;  // race condition!
    // }

    // LEARNING: using AtomicInteger for thread safety
    private final AtomicInteger counter = new AtomicInteger(0);

    public void increment() {
        counter.incrementAndGet();  // atomic operation
    }

    public int getCount() {
        return counter.get();
    }
}

